function validate([nums, k]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 30000) return 'nums needs 1 to 3 * 10^4 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 1000)) return 'Each value is an integer from 1 to 1000.';
  if (!Number.isInteger(k) || k < 0 || k > 1000000) return 'k is an integer from 0 to 10^6.';
  return null;
}

