function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const n = large ? 2000 : int(1, 10);
  // A share of 1s and small values keeps some windows long; the rest go up to the limit.
  const ones = rand() * 0.5;
  const top = large ? (rand() < 0.5 ? 1000 : 12) : int(1, 12);
  const nums = Array.from({ length: n }, () => (rand() < ones ? 1 : int(1, top)));
  const kind = rand();
  const k = kind < 0.1 ? int(0, 1) : large ? int(2, 1000000) : int(2, 300);
  return [nums, k];
}
